		} catch (error) {
			logger.warn(
				`Failed to decrypt inference-provider key for ${organizationId}/${slug}: ${getErrorMessage(error)}`,
			);
		}
	}

	return {
		kind: row.kind,
		baseUrl: row.block?.base_url,
		apiKey,
	};
}

